SELECT c.id, c.parent_id parentId, c.type_code typeCode, c.type_value typeValue, c.type_name typeName FROM t_base_dict_item c WHERE c.STATUS = 1 AND c.is_valid = 1 AND EXISTS ( SELECT f.id FROM t_base_dict_item f WHERE f.STATUS = 1 AND f.is_valid = 1 AND f.id = c.parent_id
AND f.type_code in
#{item}
) ORDER BY c.sort DESC
